import { useTranslations } from 'next-intl';
import React from 'react';

export default function TermsPage() {
    const t = useTranslations('TermsPage');

    return (
        <div className="bg-swiss-surface min-h-screen pt-32 pb-20 px-6 md:px-12">
            <div className="max-w-4xl mx-auto">
                <h1 className="text-4xl md:text-5xl font-serif text-swiss-navy mb-12">
                    {t('title')}
                </h1>
                <div className="prose prose-lg text-swiss-navy/80 max-w-none">
                    {t.rich('content', {
                        p: (chunks) => <p className="mb-6 leading-relaxed">{chunks}</p>,
                        h2: (chunks) => <h2 className="text-2xl font-bold mt-10 mb-4 text-swiss-navy">{chunks}</h2>,
                        ul: (chunks) => <ul className="list-disc pl-6 mb-6 space-y-2">{chunks}</ul>,
                        li: (chunks) => <li>{chunks}</li>,
                        strong: (chunks) => <strong className="font-semibold text-swiss-navy">{chunks}</strong>
                    })}
                </div>
            </div>
        </div>
    );
}
